      "tiers": [
        {
          "id": "practice.reps:t1",
          "title": "Первые рельсы практики",
          "phrase": "Ты накопил 100 повторений в подходах — первые рельсы практики уже уложены. Маленькая тележка довольно скрипнула.",
          "imagePrompt": "A small track-building robot with one square eye and clamp hands connects two short rail sections. An empty miniature cart waits beside a neat pile of track pieces, with the robot leaning forward to align the joint.",
          "fishMarkup": "[warm] Ты накопил 100 повторений в подходах — первые рельсы практики уже уложены. Маленькая тележка <soft>довольно скрипнула.</soft>",
          "audioText": "Ты накопил 100 повторений в подходах — первые рельсы практики уже уложены. Маленькая тележка довольно скрипнула."
        },
        {
          "id": "practice.reps:t2",
          "title": "Поворот с пассажиром",
          "phrase": "В твоей истории уже 500 повторений в подходах. Практика прошла первый поворот и даже не потеряла утку-пассажира.",
          "imagePrompt": "The small track-building robot with one square eye and clamp hands fits a curved rail into a compact oval track. A rubber duck sits snugly in the miniature cart rounding the bend, its beak tilted toward the robot.",
          "fishMarkup": "[playful] В твоей истории уже 500 повторений в подходах. Практика прошла первый поворот и даже не потеряла <emphasis>утку-пассажира.</emphasis>",
          "audioText": "В твоей истории уже 500 повторений в подходах. Практика прошла первый поворот и даже не потеряла утку-пассажира."
        },
        {
          "id": "practice.reps:t3",
          "title": "Мост из повторений",
          "phrase": "Ты накопил 1 500 повторений в подходах. Из отдельных движений вырос целый мост практики — уже есть на что оглянуться.",
          "imagePrompt": "The small track-building robot with one square eye and clamp hands secures the central span of an arched railway bridge. Above it, a miniature cart carrying the rubber duck crosses between sturdy supports made from interlocking track modules.",
          "fishMarkup": "[confident] Ты накопил 1 500 повторений в подходах. Из отдельных движений вырос <emphasis>целый мост практики</emphasis> — уже есть на что оглянуться.",
          "audioText": "Ты накопил 1 500 повторений в подходах. Из отдельных движений вырос целый мост практики — уже есть на что оглянуться."
        },
        {
          "id": "practice.reps:t4",
          "title": "Эстакада с характером",
          "phrase": "3 000 повторений в подходах уже в твоей истории. Рельсы практики вышли на эстакаду — утка пристегнулась серьёзнее.",
          "imagePrompt": "The small track-building robot with one square eye and clamp hands operates a lever beneath a sweeping elevated railway. The rubber duck rides a cart around a high banked turn, held snugly by an oversized lap bar.",
          "fishMarkup": "[excited] 3 000 повторений в подходах уже в твоей истории. Рельсы практики вышли на эстакаду — утка <emphasis>пристегнулась серьёзнее.</emphasis>",
          "audioText": "3 000 повторений в подходах уже в твоей истории. Рельсы практики вышли на эстакаду — утка пристегнулась серьёзнее."
        },
        {
          "id": "practice.reps:t5",
          "title": "Башня больших виражей",
          "phrase": "Ты накопил 7 500 повторений в подходах — рельсы практики закрутились в башню. Утка репетирует победное «кря».",
          "imagePrompt": "The small track-building robot with one square eye and clamp hands attaches the top curve of a towering spiral railway. Far below, the rubber duck's cart begins the climb, its open beak aimed toward the summit.",
          "fishMarkup": "[excited] Ты накопил 7 500 повторений в подходах — рельсы практики закрутились в башню. Утка репетирует <emphasis>победное «кря».</emphasis>",
          "audioText": "Ты накопил 7 500 повторений в подходах — рельсы практики закрутились в башню. Утка репетирует победное «кря»."
        },
        {
          "id": "practice.reps:t6",
          "title": "Грандиозное кря",
          "phrase": "Ты накопил 15 000 повторений в подходах — целый парк практики. И всё это величие возит одну резиновую утку.",
          "imagePrompt": "The small track-building robot with one square eye and clamp hands proudly opens a boarding gate beneath an enormous roller coaster of loops and spirals. Its only passenger is a tiny rubber duck in a single cart at the summit.",
          "fishMarkup": "[triumphant] Ты накопил 15 000 повторений в подходах — целый парк практики. И всё это величие возит <slow>одну резиновую утку.</slow>",
          "audioText": "Ты накопил 15 000 повторений в подходах — целый парк практики. И всё это величие возит одну резиновую утку."
        }
      ]
    },
    {
      "id": "practice.working_sets",
      "tiers": [
        {
          "id": "practice.working_sets:t1",
          "title": "Первый рабочий ритм",
          "phrase": "Ты накопил 10 рабочих подходов без учёта разминочных. Ритм практики уже слышно — даже кастрюля подыгрывает.",
          "imagePrompt": "A raccoon drummer sits on a low stool, gently tapping an upside-down saucepan with wooden spoons. One striped tail curls around the stool leg, and a small pot lid rests nearby, ready to join the improvised drum kit.",
          "fishMarkup": "[warm] Ты накопил 10 рабочих подходов без учёта разминочных. Ритм практики уже слышно — даже кастрюля <soft>подыгрывает.</soft>",
          "audioText": "Ты накопил 10 рабочих подходов без учёта разминочных. Ритм практики уже слышно — даже кастрюля подыгрывает."
        },
        {
          "id": "practice.working_sets:t2",
          "title": "Кастрюли держат ритм",
          "phrase": "Ты накопил 50 рабочих подходов, не считая разминочных. Кухонный оркестр практики уже уверенно держит ритм.",
          "imagePrompt": "The raccoon drummer plays a semicircle of saucepans and stockpots with wooden spoons. A hanging frying pan swings from a fresh strike, while the striped tail steadies a pot lid used as a pedal cymbal.",
          "fishMarkup": "[confident] Ты накопил 50 рабочих подходов, не считая разминочных. Кухонный оркестр практики уже <emphasis>уверенно держит ритм.</emphasis>",
          "audioText": "Ты накопил 50 рабочих подходов, не считая разминочных. Кухонный оркестр практики уже уверенно держит ритм."
        },
        {
          "id": "practice.working_sets:t3",
          "title": "Кастрюля большого финала",
          "phrase": "Ты накопил 150 рабочих подходов без учёта разминочных. Туш в твою честь — на главной кастрюле оркестра!",
          "imagePrompt": "The raccoon drummer stands inside a towering drum kit built from nested stockpots and suspended frying pans. Ignoring the gigantic cookware, it raises a soup ladle for a ceremonial strike on one tiny saucepan perched at the center.",
          "fishMarkup": "[triumphant] Ты накопил 150 рабочих подходов без учёта разминочных. Туш в твою честь — <slow>на главной кастрюле оркестра!</slow>",
          "audioText": "Ты накопил 150 рабочих подходов без учёта разминочных. Туш в твою честь — на главной кастрюле оркестра!"
        }
      ]
    }
